/** A value that grows linearly from [min] at 360dp wide to [max] at 1440dp. */
data class Fluid(val min: Float, val max: Float) {
    fun at(widthDp: Float): Float {
        val t = ((widthDp - FLUID_FROM) / (FLUID_TO - FLUID_FROM)).coerceIn(0f, 1f)
        return min + (max - min) * t
    }
    companion object {
        const val FLUID_FROM = 360f
        const val FLUID_TO = 1440f
    }
}

